  // Flagi funkcji czytamy też POZA Brand24. `localStorage` jest per origin, więc na Instagramie
  // czy TikToku jest pusty — a to właśnie tam używa się formularza wzmianki. Stąd kopia w pamięci
  // Tampermonkeya, dokładnie tak jak wtyczka robi to z motywem (`b24t_theme_mirror`).
  function loadFeatures() {
    try {
      var raw = lsGet(LS.FEATURES, null);
      if (raw) return JSON.parse(raw);
    } catch(e) {}
    try { return JSON.parse(GM_getValue('b24t_features_mirror', '{}')); } catch(e) { return {}; }
  }

  function saveFeatures(features) {
    var json = JSON.stringify(features);
    lsSet(LS.FEATURES, json);
    try { GM_setValue('b24t_features_mirror', json); } catch(e) {}
  }

  function applyFeatures() {
    const features = loadFeatures();
    // Pokaż opcję "Wszystkie projekty" w Quick Delete tylko gdy Annotators włączone
    const apLabel = document.getElementById('b24t-del-allprojects-label');
    if (apLabel) apLabel.style.display = features.annotator_tools ? 'flex' : 'none';

    // Annotators Tab — floating panel
    const tab = document.getElementById('b24t-annotator-tab');
    const panel = document.getElementById('b24t-annotator-panel');
    if (features.annotator_tools) {
      if (tab) tab.style.display = 'flex';
      // Show news side tab alongside annotator tab
      var _nst = document.getElementById('b24t-news-side-tab');
      if (_nst) _nst.style.display = 'flex';
      // Prefetch danych w tle — startBgPrefetch sam zarządza tokenem i cyklem
      startBgPrefetch();
    } else {
      if (tab) tab.style.display = 'none';
      if (panel) panel.style.display = 'none';
      var _nst2 = document.getElementById('b24t-news-side-tab');
      if (_nst2) _nst2.style.display = 'none';
    }

    // Network Monitor tab
    var nmTab = document.getElementById('b24t-nm-tab');
    if (nmTab) nmTab.style.display = features.network_monitor ? 'flex' : 'none';
    nmState.enabled = !!features.network_monitor;

  }

